def snapshot(game):
    b, chars = combat.Battle(game), game.s.chars()
    return dict(seed=game.s.seed, hp=[c.b[F['hp']] for c in chars], status=[c.b[F['status']] for c in chars], active=[c.b[F['active']] for c in chars],
                xy=[[r['x'], r['y']] for r in b.data['actors']], initiative=[r['initiative'] for r in b.data['actors']])


def party_end(game):
    return dict(seed=game.s.seed, experience=[int.from_bytes(c.b[F['experience']:F['experience'] + 4], 'little') for c in game.s.party], hp=[c.b[F['hp']] for c in game.s.party],
                status=[c.b[F['status']] for c in game.s.party], money=[list(c.b[F['money']:F['money'] + 14]) for c in game.s.party], items=[len(c.items) for c in game.s.party])


def digest(values):
    return hashlib.sha256(json.dumps(values, separators=(',', ':')).encode()).hexdigest()


def fixture_name(kind, seed):
    return '%s-%d' % (kind, seed)


def row_digest(row):
    return digest([row[key] for key in ('seed', 'hp', 'status', 'active', 'xy', 'initiative', 'treasure') if key in row])[:12]


def treasure_digest(money, items):
    return digest([list(money), [[bytes(i[1:1 + i[0]]).hex(), bytes(i[combat.I['type']:]).hex()] for i in items]])[:12]


def throtl(folder, bandage=False):
    session = _combat_test.ambush(folder)
    game = session.game
    try:
        _combat_test.fight(session=session)
        def choose(label):
            session.step(session.decision['options'].index(label))
            if session.error: raise session.error
        choose('LEAVE'); choose('NO')
        while tuple(game.s.r0[0xC3:0xC5]) != (2, 1):
            choose('east' if game.s.r0[0xC3] < 2 else 'north')
            if session.decision['kind'] == 'MENU' and 'THROTL' not in game.vm.out[-3:]: choose('NO')
        choose('YES'); choose('ATTACK')
        return plain(session, bandage=bandage)
    finally: session.close()


def plain(session, plan=None, bandage=False):
    from sm.titles.cok._cli import at_outpost
    game, plan, blocked = session.game, plan or {}, False
    for _ in range(3200):
        if session.error: raise session.error
        d = session.decision
        if not d: break
        kind, options = d['kind'], d['options']
        b = combat.Battle(game)
        if kind == 'COMBAT_ACTION':
            actor = d['info']['actor']
            if plan.get(actor) and 'Move' in options and (actor != 0 or b.attack_targets(0)): choice = 'Move'
            else: choice = 'Done' if blocked or bandage and any(c.b[F['status']] == 5 for c in game.s.party) else 'Aim'
            blocked = False
        elif kind == 'COMBAT_MOVE': choice = plan[b.data['actor']].pop(0) if plan.get(b.data['actor']) else 'Done'
        elif kind == 'TARGET':
            side = town.field(b.chars[b.data['actor']],'side')
            choice = next((o for o in options if '#' in o and town.field(b.chars[int(o.rsplit('#',1)[1])],'side') != side),'Exit')
            blocked = choice == 'Exit'
        elif kind == 'COMBAT_DONE': choice = 'Bandage' if bandage and 'Bandage' in options else 'Guard' if 'Guard' in options else 'Quit'
        elif kind == 'COMBAT_CONFIRM': choice = options[1]
        elif kind == 'COMBAT_LOOT': choice = 'Exit'
        elif kind == 'ACK': choice = options[0]
        elif kind == 'MENU' and game.s.g['cok.battle'].get('result') and 'THROTL' not in game.vm.out[-3:]:
            if at_outpost(session) or game.s.mode == 4 and 'PRESS' not in options[0]: break
            choice = options[0]
        else: break
        session.step(options.index(choice))
    else: raise AssertionError('fight choice limit')
    b = combat.Battle(game)
    return dict(result=b.data['result'], rounds=b.data['round'], log=game.combat_log)


def moved(folder):
    session = _combat_test.ambush(folder)
    try: return plain(session, {5: ['north'], 0: ['northeast']})
    finally: session.close()


PLAYS = dict(moved=moved, weapons=lambda folder: _combat_test.fight(folder=folder), spells=lambda folder: _combat_test.fight(folder=folder, spells=True),
             loss=lambda folder: _combat_test.fight(attack=False, folder=folder), throtl=throtl, bandage=lambda folder: throtl(folder, True))


def transcript(kind, seed, folder=None, second=None):
    rows, game, logs = [], {}, []
    original = Session.step
    def step(self, choice):
        d, g, label = self.decision, self.game, self.decision['options'][choice]
        game['g'] = g
        if d['kind'] == 'MOVE' and 'seeded' not in game: g.s.seed, game['seeded'] = seed, True
        log = getattr(g, 'combat_log', None)
        if log is not None and not any(log is seen for seen in logs): logs.append(log)
        battle = g.s.g.get('cok.battle', {})
        if d['kind'] == 'ACK' and battle.get('active'): pass
        elif battle.get('active') and battle.get('actors') and d['kind'] != 'MOVE':
            rows.append(dict(kind=d['kind'], label=label, actor=d['info'].get('actor'), round=d['info'].get('round'), **snapshot(g)))
            if d['kind'] == combat.Kind.SPELL.value:
                listed = [magic.spell(ident).level for ident, _ in magic.castable(g.s.chars()[d['info']['actor']], True)]
                rows[-1].update(move=camp.opening_row(listed, 18) - choice)
        elif rows:
            rows.append(dict(kind=d['kind'], label=label, post=True, seed=g.s.seed))
            if g.s.party: rows[-1].update(hp=[c.b[F['hp']] for c in g.s.party])
            if d['kind'] == combat.Kind.LOOT.value: rows[-1].update(treasure=treasure_digest(g.s.treasure_money, g.s.treasure_items))
        if label == 'ATTACK' and second is not None:
            g.s.seed = second
            if rows: rows[-1].update(set_seed=second)
        return original(self, choice)
    Session.step = step
    roster = _combat_test.check_roster
    audit = _combat_test.audit
    _combat_test.check_roster, _combat_test.audit = (lambda game: None), (lambda game: '')
    try: result = PLAYS[kind](folder)
    finally: Session.step, _combat_test.check_roster, _combat_test.audit = original, roster, audit
    log = [event for each in logs for event in each]
    if not any(result['log'] is each for each in logs): log += result['log']
    g = game['g']
    return rows, dict(result=result['result'], rounds=result['rounds'], damage=[[e['target'], e['hp']] for e in log if e['event'] in ('damage', 'heal')],
                      experience=[[e['actor'], e['amount']] for e in log if e['event'] == 'experience'], attacks=[[e['actor'], e['target'], int(e['hit'])] for e in log if e['event'] == 'attack'],
                      seeds=[e['after'] for e in log if e['event'] == 'dice'], end=party_end(g), party_dead=bool(g.s.party_dead),
                      struck_on_move=[[e['actor'], e['target'], int(e['hit'])] for before, e in zip(log, log[1:]) if e['event'] == 'attack' and before['event'] in ('move', 'dice') and any(m['event'] == 'move' for m in log[max(0, log.index(e) - 3):log.index(e)])])


def played(kind, seed, folder=None):
    start, second = (0, seed) if kind in ('throtl', 'bandage') else (seed, None)
    return (start,) + transcript(kind, start, folder, second)


def differences(kind, seed, folder=None):
    _, rows, outcome = played(kind, seed, folder)
    recorded, found = ORIGINAL[fixture_name(kind, seed)], {}
    if len(rows) != len(recorded['rows']): found['rows'] = (len(recorded['rows']), len(rows))
    for index, (theirs, ours) in enumerate(zip(recorded['rows'], rows)):
        if theirs != row_digest(ours): found[index] = (ours['kind'], ours['label'], ours['seed'])
    if recorded['seeds_sha'] != digest(outcome['seeds'][:recorded['seeds_count']]): found['seeds'] = 'differs'
    if recorded['damage'] != outcome['damage']: found['damage'] = (recorded['damage'], outcome['damage'])
    if recorded['end'] and recorded['end'] != outcome['end']: found['end'] = (recorded['end'], outcome['end'])
    return found


def test(folder=None):
    folder = folder or os.environ.get('SM_COK')
    if not folder or not Path(folder).is_dir(): raise SkipTest('SM_COK is not set')
    if not ORIGINAL: raise SkipTest('no recorded original rounds')
    found = {name: differences(*name, folder) for name in FIGHTS}
    assert not any(found.values()), found
    return 'PASS ambush against the original, %d fights: %d decisions equal' % (len(FIGHTS), sum(len(row['rows']) for row in ORIGINAL.values()))


if __name__ == '__main__':
    if len(sys.argv) > 2 and sys.argv[1] == 'dump':
        print(json.dumps(transcript(int(sys.argv[2]))))
    else:
        print(test(sys.argv[1] if len(sys.argv) > 1 else None))
